function validate([code, k]) {
  if (!Array.isArray(code) || code.length < 1 || code.length > 100) return 'code needs 1 to 100 values.';
  if (code.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value of code is an integer from 1 to 100.';
  if (!Number.isInteger(k) || Math.abs(k) > code.length - 1) return 'k must be between -(n - 1) and n - 1.';
  return null;
}

