function decrypt(code, k) {
  const n = code.length;
  return code.map((_, i) => {
    let sum = 0;
    for (let step = 1; step <= Math.abs(k); step++) {
      const at = k > 0 ? i + step : i - step;
      sum += code[((at % n) + n) % n];
    }
    return sum;
  });
}

