function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const top = rand() < 0.3 ? 3 : 100;
  const code = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const k = Math.floor(rand() * (2 * n - 1)) - (n - 1);
  return [code, k];
}
